sys_script.script:
(function executeRule(current, previous) {

    // Validate only when moving to Result Verified.
    if (!current.status.changes() || current.getDisplayValue('status') != 'Result Verified') {
        return;
    }

    // The user performing this transition must have Lab Staff access.
    if (!gs.hasRole('x_2223823_apollo_0.lab_staff')) {
        gs.addErrorMessage(
            'Only Lab Staff can verify a lab result.'
        );
        current.setAbortAction(true);
        return;
    }

    var technicianId = current.getValue('technician');
    var verifierId = current.getValue('verifier');

    if (!technicianId || !verifierId) {
        gs.addErrorMessage(
            'Both Technician and Verifier must be selected.'
        );
        current.setAbortAction(true);
        return;
    }

    if (technicianId == verifierId) {
        gs.addErrorMessage(
            'The Verifier must be different from the Technician.'
        );
        current.setAbortAction(true);
        return;
    }

    // Validate the selected verifier Staff record.
    var verifier = new GlideRecord(
        'x_2223823_apollo_0_staff'
    );

    if (!verifier.get(verifierId)) {
        gs.addErrorMessage('The selected Verifier was not found.');
        current.setAbortAction(true);
        return;
    }

    if (verifier.getValue('staff_role') != 'lab_technician') {
        gs.addErrorMessage(
            'The selected Verifier must be an eligible Lab Staff member.'
        );
        current.setAbortAction(true);
        return;
    }

    // The selected verifier must be the logged-in user.
    if (verifier.getValue('user') != gs.getUserID()) {
        gs.addErrorMessage(
            'You must be selected as the Verifier to verify this result.'
        );
        current.setAbortAction(true);
        return;
    }

    // Record the verification timestamp.
    current.setValue('verified_at', new GlideDateTime());

})(current, previous);
